/* Form presentation layer. build.mjs includes this in the app's private closure. */
function referencePrograms(){
  return [...new Map(REFERENCE_FUNCTIONS.filter(r=>r.category==='Strategic').map(r=>[r.program,{name:r.program,outcome:r.outcome}])).values()];
}
function normalizeProgram(value){return String(value||'').toUpperCase().replace(/\s+/g,' ').trim();}
function currentSignoff(r,role){
  const start=r.history.findLastIndex(h=>['Submitted','Resubmitted'].includes(h.action));
  const action=['Draft','Returned'].includes(r.status)?null:r.history.slice(Math.max(0,start)).findLast(h=>h.role===role&&(h.action==='Approved and forwarded'||h.action==='Final approval · Completed'));
  const assigned=db.users.find(u=>u.active&&u.role===role&&(role!=='Department Head'||u.unit===r.unit&&u.department===r.department)&&(role!=='Dean'||u.unit===r.unit));
  return {name:action?.actor||assigned?.name||'Not assigned',date:action?.at||'',approved:!!action};
}
function ratingLegend(){return `<aside class="ipcr-legend" aria-label="Rating legend"><strong>Rating legend</strong><span>5 – Outstanding</span><span>4 – Very Satisfactory</span><span>3 – Satisfactory</span><span>2 – Unsatisfactory</span><span>1 – Poor</span><small>Q – Quality &nbsp; E – Efficiency &nbsp; T – Timeliness &nbsp; A – Average</small></aside>`;}
function formalReviewFields(r){
  const head=currentSignoff(r,'Department Head'),president=currentSignoff(r,'President');
  return `<div class="table-wrap"><table class="ipcr-review-table"><thead><tr><th>Reviewed by</th><th>Date</th><th>Approved by</th><th>Date</th></tr></thead><tbody><tr><td><strong>${esc(head.name)}</strong><small>Immediate Supervisor</small>${head.approved?'':'<span class="signature-pending">Pending review</span>'}</td><td>${head.date?date(head.date):'________________'}</td><td><strong>${esc(president.name)}</strong><small>Head of Office · University President</small>${president.approved?'':'<span class="signature-pending">Pending approval</span>'}</td><td>${president.date?date(president.date):'________________'}</td></tr></tbody></table></div>`;
}
function ipcrFooter(r,editable=false){
  const vp=currentSignoff(r,'Vice President'),president=currentSignoff(r,'President');
  return `<div class="ipcr-signatures signature-grid"><div class="signature"><h3>Discussed with:</h3><div class="signature-name">${esc(r.name)}</div><span>Employee</span>${editable?field('Date of discussion','record-discussionDate',r.discussionDate||'','date','data-record="discussionDate"'):`<p>Date: ${r.discussionDate?date(r.discussionDate):'________________'}</p>`}</div><div class="signature"><h3>Assessed by:</h3><p class="certification">I certify that I discussed my assessment of the performance with the employee.</p><div class="signature-name">${esc(vp.name)}</div><span>VPAA / Vice President</span><p>Date: ${vp.date?date(vp.date):'________________'}</p>${vp.approved?'':'<small class="signature-pending">Assessment pending</small>'}</div><div class="signature"><h3>Final Rating by:</h3><div class="signature-name">${esc(president.name)}</div><span>University President</span><p>Date: ${president.date?date(president.date):'________________'}</p>${president.approved?'':'<small class="signature-pending">Final approval pending</small>'}</div></div>`;
}
function ipcrTableHeader(){return `<colgroup><col class="indicator-col"><col class="target-col"><col class="actual-col"><col class="number-col"><col class="number-col"><col class="number-col"><col class="number-col"><col class="remarks-col"></colgroup><thead><tr><th rowspan="2" scope="col">Performance indicators / functions</th><th rowspan="2" scope="col">TARGETS</th><th rowspan="2" scope="col">Actual Accomplishment</th><th colspan="4" scope="colgroup">Rating</th><th rowspan="2" scope="col">Remarks</th></tr><tr>${['Q','E','T','A'].map(c=>`<th scope="col"><abbr title="${{Q:'Quality',E:'Efficiency',T:'Timeliness',A:'Average'}[c]}">${c}</abbr></th>`).join('')}</tr></thead>`;}
function ipcrSectionRows(r,category,editable=false){
  const rows=r.rows.filter(row=>row.category===category),used=new Set(),programs=category==='Strategic'&&r.type==='Teaching'?referencePrograms():[];
  let html=`<tr class="ipcr-category"><th colspan="8" scope="rowgroup">${category==='Strategic'?'STRATEGIC FUNCTION':category.toUpperCase()+' FUNCTIONS'} <span>${settingsFor(r).weights[CATEGORIES.indexOf(category)]}%</span></th></tr>`;
  const printRow=row=>`<tr class="ipcr-entry ${row.applicable?'':'na'}"><td>${esc(row.indicator)}${row.applicable?'':' <small>(Not applicable)</small>'}</td><td>${esc(row.target)||'—'}</td><td>${esc(row.actual)||'—'}</td>${['q','e','t'].map(k=>`<td class="numeric">${row.applicable?esc(row[k])||'—':'N/A'}</td>`).join('')}<td class="numeric">${row.applicable?fmt(rowAverage(row)):'N/A'}</td><td>${esc(row.remarks)||'—'}</td></tr>`;
  const draw=items=>items.map(row=>{used.add(row.id);return editable?renderIPCRRow(row,r.rows.indexOf(row)):printRow(row);}).join('');
  const blank='<tr class="ipcr-placeholder"><td colspan="8">No entries in this group. Add applicable functions as needed.</td></tr>';
  for(const program of programs){
    const group=rows.filter(row=>normalizeProgram(row.program)===normalizeProgram(program.name));
    html+=`<tr class="ipcr-program"><th colspan="8">${esc(program.name)}</th></tr>`;
    const outcomes=[...new Set([program.outcome,...group.map(row=>row.outcome).filter(Boolean)])];
    for(const outcome of outcomes){
      const outcomeRows=group.filter(row=>(row.outcome||program.outcome)===outcome);
      html+=`<tr class="ipcr-outcome"><td colspan="8">${esc(outcome)}</td></tr>`;
      for(const kind of ['Outcome indicator','Output indicator','Function']){
        const entries=outcomeRows.filter(row=>(row.indicatorType||'Function')===kind);
        if(kind==='Function'&&!entries.length)continue;
        html+=`<tr class="ipcr-indicator-kind"><th colspan="8">${kind==='Function'?'OTHER FUNCTIONS':kind.toUpperCase()+'S'}</th></tr>${entries.length?draw(entries):blank}`;
      }
    }
  }
  const remaining=rows.filter(row=>!used.has(row.id));
  for(const program of [...new Set(remaining.map(row=>row.program||''))]){
    const group=remaining.filter(row=>(row.program||'')===program);
    if(program)html+=`<tr class="ipcr-program"><th colspan="8">${esc(program)}</th></tr>`;
    let previousOutcome='',previousKind='';
    for(const row of group){
      if(row.outcome&&row.outcome!==previousOutcome){html+=`<tr class="ipcr-outcome"><td colspan="8">${esc(row.outcome)}</td></tr>`;previousOutcome=row.outcome;}
      if(category==='Strategic'&&row.indicatorType&&row.indicatorType!==previousKind){html+=`<tr class="ipcr-indicator-kind"><th colspan="8">${esc(row.indicatorType.toUpperCase())}S</th></tr>`;previousKind=row.indicatorType;}
      html+=draw([row]);
    }
  }
  if(!rows.length&&!programs.length)html+=blank;
  if(category==='Core'&&r.type==='Teaching'&&!rows.some(row=>row.program==='Functions of University Designations'))html+=`<tr class="ipcr-program"><th colspan="8">Functions of University Designations (e.g. Dean, Director, Chief, etc.)</th></tr><tr class="ipcr-outcome"><td colspan="8">Functions should be based on the Special Order issued to the faculty member. Add rows if needed.</td></tr>`;
  return html;
}
function renderIPCRRow(row,index){
  return `<tr class="ipcr-entry ${row.applicable?'':'na'}" data-row="${row.id}"><td data-label="Performance indicator / function"><div class="row-title"><span>Function ${index+1}</span><button class="icon-btn delete-row" aria-label="Delete function ${index+1}" data-delete="${row.id}">${icon('trash3')}</button></div><textarea class="form-control" aria-label="Performance indicator" data-key="indicator">${esc(row.indicator)}</textarea><label class="inline-check"><input type="checkbox" data-key="applicable" ${row.applicable?'checked':''}> Applicable</label><details class="row-classification"><summary>Program & indicator grouping</summary><label>Program / designation</label><input class="form-control" aria-label="Program or outcome" data-key="program" list="ipcr-programs" value="${esc(row.program)}" placeholder="Program or designation"><label>Organizational outcome</label><input class="form-control" aria-label="Organizational outcome" data-key="outcome" value="${esc(row.outcome)}" placeholder="e.g. OO1: Relevant and quality tertiary education"><label>Indicator type</label><select class="form-select" aria-label="Indicator type" data-key="indicatorType">${options(['Outcome indicator','Output indicator','Function'],row.indicatorType)}</select></details></td><td data-label="Targets"><textarea class="form-control" aria-label="Target" data-key="target">${esc(row.target)}</textarea></td><td data-label="Actual Accomplishment"><textarea class="form-control" aria-label="Actual accomplishment" data-key="actual" placeholder="Record actual accomplishment">${esc(row.actual)}</textarea></td>${['q','e','t'].map((k,i)=>`<td class="numeric" data-label="${['Quality (Q)','Efficiency (E)','Timeliness (T)'][i]}"><input class="form-control" aria-label="${['Quality','Efficiency','Timeliness'][i]}" type="number" min="1" max="5" step="0.01" data-key="${k}" value="${esc(row[k])}" placeholder="1–5"></td>`).join('')}<td class="numeric average-cell" data-label="Average (A)"><strong class="row-average">${row.applicable?fmt(rowAverage(row)):'N/A'}</strong></td><td data-label="Remarks"><textarea class="form-control" aria-label="Remarks" data-key="remarks" placeholder="Evidence / notes">${esc(row.remarks)}</textarea></td></tr>`;
}
function renderIPCRSummary(r,editable=false){
  const s=rating(r,settingsFor(r)),weightTotal=settingsFor(r).weights.reduce((a,b)=>a+b,0);
  return `<h2>Rating summary</h2><div class="table-wrap"><table class="ipcr-summary-table"><thead><tr><th>CATEGORY</th><th>MFO</th><th>RATING</th></tr></thead><tbody>${s.categories.map(c=>{
    const values=r.rows.filter(row=>row.category===c.name&&row.applicable).map(rowAverage).filter(v=>v!==null),sum=values.reduce((a,b)=>a+b,0),weighted=c.weight===0?0:c.average===null?null:c.average*c.weight/100;
    return `<tr><th scope="row">${c.name} Functions</th><td>${editable?`<input class="form-control" aria-label="${c.name} MFO" data-mfo="${c.name}" value="${esc(r.mfo?.[c.name]||'')}" placeholder="${c.name==='Strategic'?'e.g. MFO1, MFO3, MFO4':'MFO reference'}">`:esc(r.mfo?.[c.name]||'—')}</td><td>${c.average===null?'No applicable rated entries':`${fmt(sum)} ÷ ${values.length} = ${fmt(c.average)}`} × ${(c.weight/100).toFixed(2)} = <strong>${fmt(weighted)}</strong></td></tr>`;
  }).join('')}<tr class="summary-total"><th colspan="2">Total Overall Rating <small>Sum of weighted category ratings</small></th><td><strong>${fmt(s.total)}</strong></td></tr><tr><th colspan="2">Final Average Rating <small>Weighted overall / total weight (${weightTotal}%)</small></th><td><strong>${fmt(s.total===null?null:s.total/(weightTotal/100))} / 5.00</strong></td></tr><tr><th colspan="2">Adjective Rating</th><td><strong>${s.label}</strong></td></tr></tbody></table></div><p class="rating-policy">Provisional formula: A = (Q + E + T) ÷ 3; category mean × weight; sum weighted means. Thresholds: ${settingsFor(r).scale.map(s=>`${s.min.toFixed(2)}+ ${s.label}`).join(' · ')}. Verify against current MMSU policy. Unrated and non-applicable rows are excluded.</p>${s.categories.filter(c=>c.weight>0&&c.average===null).map(c=>`<div class="notice warning">${c.name} has no applicable fully rated entries.</div>`).join('')}`;
}
function renderIPCREditor(category='Strategic',id){
  if(!employee(user))return forbidden();
  if(category==='new'){createRecord();return;}
  if(!CATEGORIES.includes(category))category='Strategic';
  let r=id?db.records.find(x=>x.id===id):db.records.find(x=>x.id===currentEdit&&canEdit(user,x))||db.records.find(x=>canEdit(user,x));
  if(!r){createRecord();return;}if(!canEdit(user,r))return forbidden();currentEdit=r.id;
  const latestReturn=[...r.history].reverse().find(h=>h.action==='Returned for correction');
  shell(heading(r.status==='Returned'?'Correct your IPCR':'Create / edit IPCR',`${esc(periodName(r.period))} · ${esc(r.id)}`,badge(r.status))+`${latestReturn&&r.status==='Returned'?`<div class="notice error"><strong>Returned by ${esc(latestReturn.actor)}</strong><br>${esc(latestReturn.comment)}<br>Resubmission restarts at the Department Head.</div>`:''}
  <div class="ipcr-editor stack"><section class="panel"><div class="panel-head"><h2>Individual Performance Commitment and Review (IPCR)</h2><span id="save-status" class="small">All changes saved</span></div><div class="panel-body"><div class="form-grid">${field('Employee name','record-name',r.name,'text','data-record="name" required')}${field('Position','record-position',r.position,'text','data-record="position" required')}${field('Unit / office','record-unit',r.unit,'text','readonly')}${field('Department','record-department',r.department,'text','readonly')}${selectField('Evaluation period','record-period',db.periods.filter(p=>user.periodIds?.includes(p.id)||p.id===r.period),r.period)}${field('Employee type','record-type',r.type,'text','readonly')}<div class="field full"><label for="record-commitment">Commitment statement</label><p class="small muted">I, the employee named above, of the indicated unit, Mariano Marcos State University, Batac City, Ilocos Norte:</p><textarea class="form-control" id="record-commitment" data-record="commitment">${esc(r.commitment)}</textarea><p class="small muted" style="margin-top:8px">For the evaluation period selected above.</p></div></div><div class="ratee-editor"><div><strong id="ratee-display">${esc(r.name)}</strong><span>Ratee</span></div>${field('Ratee date','record-rateeDate',r.rateeDate||'','date','data-record="rateeDate"')}</div>${formalReviewFields(r)}<p class="small muted" style="margin:10px 0 0">Review and approval names/dates follow the current submission’s workflow. Pending fields are not signatures.</p></div></section>
  ${ratingLegend()}<section class="panel"><div class="panel-head"><div><h2>Performance commitments & accomplishments</h2><p class="small">Choose a section; entries in the other sections stay saved.</p></div></div><nav class="step-tabs" aria-label="IPCR function sections">${CATEGORIES.map((c,i)=>`<a class="${category===c?'active':''}" href="#edit/${c}/${r.id}"><span class="step-number">${i+1}</span>${c} Functions</a>`).join('')}</nav><div id="editor-errors" role="alert"></div><datalist id="ipcr-programs">${referencePrograms().map(p=>`<option value="${esc(p.name)}">`).join('')}<option value="Functions of University Designations"></datalist><div class="table-wrap ipcr-edit-scroll"><table class="ipcr-table editable-table">${ipcrTableHeader()}<tbody id="function-rows">${ipcrSectionRows(r,category,true)}</tbody></table></div><div class="ipcr-table-actions"><button class="btn btn-light" id="add-row">${icon('plus-lg')} Add function</button>${r.type==='Teaching'?'<button class="btn btn-light" id="add-reference">Add functions from sample</button>':''}<span class="small muted">Q / E / T: 1–5 · A is calculated automatically</span></div></section>
  <section class="panel panel-body" id="rating-summary">${renderIPCRSummary(r,true)}</section><section class="panel"><div class="panel-head"><h2>Comments / Recommendations for development plan</h2></div><div class="panel-body"><label class="sr-only" for="record-development">Comments / recommendations for a development plan</label><textarea id="record-development" data-record="development" class="form-control" placeholder="Development needs, recommended action, and support required…">${esc(r.development)}</textarea>${ipcrFooter(r,true)}</div></section><div class="editor-actions"><button class="btn btn-light" id="save-draft">${icon('floppy')} Save draft</button><div class="actions">${link('Preview full form','detail/'+r.id,'btn btn-light','eye')}<button class="btn btn-primary" id="submit-ipcr">${r.status==='Returned'?'Resubmit IPCR':'Submit IPCR'} ${icon('send')}</button></div></div></div>`,category+' Functions');
  bindIPCREditor(r,category);
}
function bindIPCREditor(r,category){
  const save=()=>{r.updated=now();scheduleSave(r);const el=$('#save-status');if(el)el.textContent='Saving\u2026';};
  const bindMfo=()=>$$('[data-mfo]').forEach(input=>input.oninput=()=>{r.mfo??={};r.mfo[input.dataset.mfo]=input.value;save();});
  const update=()=>{save();$('#rating-summary').innerHTML=renderIPCRSummary(r,true);bindMfo();};
  bindMfo();
  $$('[data-record]').forEach(input=>input.oninput=()=>{r[input.dataset.record]=input.value;if(input.dataset.record==='name')$('#ratee-display').textContent=input.value;save();});
  $('#record-period').onchange=e=>{r.period=e.target.value;save();};
  $$('[data-row]').forEach(card=>{const row=r.rows.find(x=>x.id===card.dataset.row);card.querySelectorAll('[data-key]').forEach(input=>{input.oninput=()=>{row[input.dataset.key]=input.type==='checkbox'?input.checked:input.value;card.classList.toggle('na',!row.applicable);card.querySelector('.row-average').textContent=row.applicable?fmt(rowAverage(row)):'N/A';update();};});});
  $$('[data-delete]').forEach(b=>b.onclick=async()=>{if(await confirmAction('Delete function?','This function and its entered ratings will be removed from the draft.','Delete function')){r.rows=r.rows.filter(x=>x.id!==b.dataset.delete);save();renderIPCREditor(category,r.id);}});
  $('#add-row').onclick=()=>{r.rows.push({id:uid(),category,applicable:true,program:'',outcome:'',indicatorType:'Function',indicator:'',target:'',actual:'',q:'',e:'',t:'',remarks:''});save();renderIPCREditor(category,r.id);const added=$$('[data-row]').at(-1);added?.scrollIntoView({behavior:'smooth',block:'center'});};
  if($('#add-reference'))$('#add-reference').onclick=async()=>{
    const rows=REFERENCE_FUNCTIONS.filter(row=>row.category===category&&!r.rows.some(existing=>existing.category===category&&existing.indicator===row.indicator));
    if(!rows.length)return toast('All sample functions for this section are already present.');
    if(await confirmAction('Add sample functions?',`Append ${rows.length} ${category.toLowerCase()} functions from the old form. Existing entries are preserved. Targets are reference examples; review their applicability before submitting.`,'Add functions')){
      r.rows.push(...rows.map(row=>({...structuredClone(row),id:uid(),applicable:true,actual:'',q:'',e:'',t:'',remarks:''})));save();renderIPCREditor(category,r.id);toast('Reference functions added. Existing entries were preserved.');
    }
  };
  $('#save-draft').onclick=()=>{const errors=validateRecord(r);$('#editor-errors').innerHTML=errors.length?`<div class="notice error error-list">${errors.map(esc).join('<br>')}</div>`:'';if(!errors.length)flushSave().then(ok=>{if(ok)toast('Draft saved. You can continue from any function section.');});};
  $('#submit-ipcr').onclick=async()=>{const errors=validateRecord(r,true);if(errors.length){$('#editor-errors').innerHTML=`<div class="notice error error-list">${errors.map(esc).join('<br>')}</div>`;$('#editor-errors').scrollIntoView({behavior:'smooth'});return;}const incomplete=rating(r,db.settings).total===null;if(await confirmAction('Submit this IPCR?',`The form will be sent to your Department Head.${incomplete?' Some categories are not fully rated; the total remains unrated.':''} You can edit it again only if it is returned for correction.`,'Submit IPCR')){try{if(!await flushSave())return;await apiTransition(r,'submit');toast('IPCR submitted to the Department Head.');location.hash='tracking/'+r.id;}catch(e){toast(e.message,'error');}}};
}
function renderFullIPCR(r){
  const p=db.periods.find(p=>p.id===r.period),period=p?`${date(p.start)} – ${date(p.end)}`:periodName(r.period),rateeDate=r.rateeDate||r.submissions.at(-1)?.at||'';
  return `<article class="print-sheet ipcr-paper"><h2>INDIVIDUAL PERFORMANCE COMMITMENT AND REVIEW (IPCR)</h2><p class="ipcr-commitment">I, <strong>${esc(r.name)}</strong>, <strong>${esc(r.position)}</strong> of the <strong>${esc(r.unit)}</strong>, Mariano Marcos State University, Batac City, Ilocos Norte, ${esc(r.commitment.replace(/^I\s+/i,''))} <span>For the period <strong>${esc(period)}</strong>.</span></p><div class="ipcr-ratee"><strong>${esc(r.name)}</strong><span>Ratee</span><span>Date: ${rateeDate?date(rateeDate):'________________'}</span></div>${formalReviewFields(r)}${ratingLegend()}<div class="table-wrap"><table class="ipcr-table">${ipcrTableHeader()}<tbody>${CATEGORIES.map(c=>ipcrSectionRows(r,c)).join('')}</tbody></table></div><section class="ipcr-summary">${renderIPCRSummary(r)}</section><section class="ipcr-development"><h3>Comments/Recommendations for development plan:</h3><p>${esc(r.development)||'________________________________________________________________________________'}</p></section>${ipcrFooter(r)}<p class="paper-disclaimer">Prototype record · Pending fields are not signatures. Formal review fields show the current submission only; all earlier actions remain in the history.</p></article>`;
}
